local config = {
  ui_story_40200001_1_dialog_content = "Hey PlayerName...",
  ui_story_40200001_2_dialog_content = "Oh wait, you're <color=#FFB400>Nameless</color> now, right?",
  ui_story_40200001_3_dialog_content = "You're holding the <color=#FFB400>Covenant of the Hidden Moon</color>.",
  ui_story_40200001_4_dialog_content = "Bring this letter tonight with you to Vortex, be there at midnight.",
  ui_story_40200001_5_dialog_content = "Once you arrive...",
  ui_story_40200001_6_dialog_content = "All will be revealed.",
  ui_story_40200001_7_dialog_content = "Hidden Moon Reading Club",
  ui_story_40200001_8_dialog_content = "(Let me start from the beginning...)",
  ui_story_40200001_9_dialog_content = "...",
  ui_story_40200001_10_dialog_content = "It's just an invitation to a reading club. Why are you so nervous?",
  ui_story_40200001_11_dialog_content = "But it's a reading club for the True Order! There's no way it could be a regular reading club, right?",
  ui_story_40200001_12_dialog_content = "Hey don't be so judgy, there's nothing weird and they welcome everyone.",
  ui_story_40200001_13_dialog_content = "Then why aren't you going?!",
  ui_story_40200001_14_dialog_content = "Well, obviously because I'm going to the First Faction's event.",
  ui_story_40200001_15_dialog_content = "Someone has to put those obnoxious clowns in their place, after all!",
  ui_story_40200001_16_dialog_content = "Then I can spend a wonderful afternoon with Victoria... she's so beautiful.",
  ui_story_40200001_17_dialog_content = "However, I can't just ignore the others; if they aren't able to gather at least five people for their reading club, they'll be really upset.",
  ui_story_40200001_18_dialog_content = "Something bad is definitely going to happen if they don't get what they want!",
  ui_story_40200001_19_dialog_content = "If it's that bad, then why are you smiling...",
  ui_story_40200001_20_dialog_content = "Anyways... I'm leaving it to you, so good luck!",
  ui_story_40200001_21_dialog_content = "Oh, and take these books with you. You might need them!",
  ui_story_40200001_22_dialog_content = "I'm coming for you, Victoria...!",
  ui_story_40200001_23_dialog_content = "(She didn't even give me the chance to refuse...)",
  ui_story_40200001_24_dialog_content = "(That's how it went. Soon after, I started my journey to Vortex.)",
  ui_story_40200001_25_dialog_content = "According to the address on the letter, I'm in Vortex now. Next, I have to enter the dark underground...",
  ui_story_40200001_26_dialog_content = "Err...",
  ui_story_40200001_27_dialog_content = "S-Skulls...",
  ui_story_40200001_28_dialog_content = "What are these things, torture devices?! They're covered in spikes!",
  ui_story_40200001_29_dialog_content = "A-And that scary-looking shadow...",
  ui_story_40200001_30_dialog_content = "PlayerName.",
  ui_story_40200001_31_dialog_content = "<anim type=Shake><size=45>Aaaaaah!!!</size></anim>",
  ui_story_40200001_32_dialog_content = "Why are you so scared?",
  ui_story_40200001_33_dialog_content = "Bonacie?!",
  ui_story_40200001_34_dialog_content = "Hold on, when we're here, you need to call me <color=#FFB400>Lover</color>.",
  ui_story_40200001_35_dialog_content = "That is way too weird!",
  ui_story_40200001_36_dialog_content = "Well, It seems you'll be standing in for Nameless.",
  ui_story_40200001_37_dialog_content = "Eicy is the one who told me I had to come...",
  ui_story_40200001_38_dialog_content = "I know, and I'm sure she's looking for Lady Victoria as we speak.",
  ui_story_40200001_39_dialog_content = "However, seeing as you are standing in for Nameless, you will need to follow our rules and etiquette to attend our reading club.",
  ui_story_40200001_40_dialog_content = "Just as it's written on the letter.",
  ui_story_40200001_41_dialog_content = "On the night of a full moon, <color=#FFB400>Maiden</color>, <color=#FFB400>Lover</color>, <color=#FFB400>Lady</color>, <color=#FFB400>Duchess</color>, and <color=#FFB400>Nameless</color> shall assemble.",
  ui_story_40200001_42_dialog_content = "Together, they shall read stories and novels beneath the moonlight. This is the <color=#FFB400>Hidden Moon Reading Club</color>.",
  ui_story_40200001_43_dialog_content = "Is that all you do? Read books?",
  ui_story_40200001_44_dialog_content = "Then what's with all the skulls and torture devices...?",
  ui_story_40200001_45_dialog_content = "Oh, those belonged to the original Nameless. She couldn't find anywhere to place them in her room, so she put them here.",
  ui_story_40200001_46_dialog_content = "The original Nameless?",
  ui_story_40200001_47_dialog_content = "Oh, you mean Eicy! I don't get why you need aliases for a reading club. It seems kind of complicated...",
  ui_story_40200001_48_dialog_content = "A sense of ritual is very important, PlayerName.",
  ui_story_40200001_49_dialog_content = "Genevieve?",
  ui_story_40200001_50_dialog_content = "With all due respect, you will refer to me as <color=#FFB400>Lady</color>.",
  ui_story_40200001_51_dialog_content = "Just like the drink I made you once before, my identity here is Lady.",
  ui_story_40200001_52_dialog_content = "In this reading club, we choose our code names based on words that match our characteristics.",
  ui_story_40200001_53_dialog_content = "<size=30>Sorry I'm late...</size>",
  ui_story_40200001_54_dialog_content = "Good, now we just need to wait for <color=#FFB400>Duchess</color>.",
  ui_story_40200001_55_dialog_content = "May the Truth bless you.",
  ui_story_40200001_56_dialog_content = "(Sikare's here, too...)",
  ui_story_40200001_57_dialog_content = "Now that we are all here, we can finally begin.",
  ui_story_40200001_58_dialog_content = "Before discussing tonight's topic, let's first show our gratitude towards our new Nameless.",
  ui_story_40200001_59_dialog_content = "Thanks to all the books amassed on the Colossus, we have more than enough materials for our discussion and enjoyment.",
  ui_story_40200001_60_dialog_content = "T-Thank you for buying the books I want to read...",
  ui_story_40200001_61_dialog_content = "Huh?",
  ui_story_40200001_62_dialog_content = "(Oh, Beryl must be talking about books meant for <color=#FFB400>young girls</color>.)",
  ui_story_40200001_63_dialog_content = "Now then, the topic for our reading club tonight is <color=#FFB400>love</color>.",
  ui_story_40200001_64_dialog_content = "Me first! Me first!",
  ui_story_40200001_65_dialog_content = "Hmm, excited tonight, aren't we?",
  ui_story_40200001_66_dialog_content = "I'm an expert on the subject, so naturally I should go first!",
  ui_story_40200001_67_dialog_content = "My friends, what exactly IS <color=#FFB400>love</color>?",
  ui_story_40200001_68_dialog_content = "I once thought love was noble and reserved, but it's also chaotic and uncontrollable.",
  ui_story_40200001_69_dialog_content = "Like a prize horse running free, or an overly-full glass of spirits.",
  ui_story_40200001_70_dialog_content = "The work I would recommend on the topic is a novel called \"Tumultuous Ties.\"",
  ui_story_40200001_71_dialog_content = "It perfectly demonstrates the complexities of love.",
  ui_story_40200001_72_dialog_content = "A destitute <color=#FFB400>Umbraton boy</color> and a lonesome <color=#FFB400>Umbraton girl</color> fall in love, and agree to support one another.",
  ui_story_40200001_73_dialog_content = "But one day, the boy from Umbraton discovers that he is actually the <color=#FFB400>illegitimate son of a Lumopolis nobleman</color>.",
  ui_story_40200001_74_dialog_content = "As if a stairway to the stars suddenly landed at his feet, all of the fame, wealth, and power he could ever want was suddenly in reach.",
  ui_story_40200001_75_dialog_content = "The purity and passion of his original love had begun to fade because of this; his father had also arranged for him a <color=#FFB400>fiancée</color>.",
  ui_story_40200001_76_dialog_content = "Who will he choose? The Umbraton girl he has always known and loved? Or his father's choice, his noble bride-to-be?",
  ui_story_40200001_77_dialog_content = "<size=30>The Umbraton girl, right...?</size>",
  ui_story_40200001_78_dialog_content = "Huh?",
  ui_story_40200001_79_dialog_content = "I-It's nothing, forget I said anything...",
  ui_story_40200001_80_dialog_content = "What do you think, Nameless?",
  ui_story_40200001_81_option_content = "The Umbraton girl",
  ui_story_40200001_82_dialog_content = "Love is a powerful and resilient emotion. It wouldn't be so easily affected by material gain.",
  ui_story_40200001_83_option_content = "The noble girl",
  ui_story_40200001_84_dialog_content = "They're not part of the same world anymore. The difference in their economic standing would only end up diminishing their love for each other.",
  ui_story_40200001_85_dialog_content = "I think the noble girl would be the better choice.",
  ui_story_40200001_86_dialog_content = "So that's what you think, hmm?",
  ui_story_40200001_87_dialog_content = "There is no right or wrong choice. If it were that simple, there would be no hardships when it comes to love.",
  ui_story_40200001_88_dialog_content = "Later in the story, the Umbraton girl stumbles upon <color=#FFB400>a young nobleman in the wilderness, and rescues him</color>.",
  ui_story_40200001_89_dialog_content = "This nobleman also develops feelings for her.",
  ui_story_40200001_90_dialog_content = "When you saved my life, I fell for you at first sight.",
  ui_story_40200001_91_dialog_content = "But I...",
  ui_story_40200001_92_dialog_content = "But then, it turns out that this nobleman's family and the Umbraton boy's family were caught in a <color=#FFB400>blood feud</color>...",
  ui_story_40200001_93_dialog_content = "If you were the Umbraton girl, who would you choose?",
  ui_story_40200001_94_dialog_content = "<size=30>Who? Ugh, this is too much...</size>",
  ui_story_40200001_95_dialog_content = "(Beryl seems to be muttering to herself again.)",
  ui_story_40200001_96_option_content = "The nobleman",
  ui_story_40200001_97_dialog_content = "Love at first sight, and abandoning an old love for a new life... That has its complexities, as well.",
  ui_story_40200001_98_dialog_content = "On its own, it would have all the makings of a good story... But that isn't how this one truly ends.",
  ui_story_40200001_99_dialog_content = "The true ending of the story is that...",
  ui_story_40200001_100_dialog_content = "<color=#FFB400>The Umbraton girl and the noble girl end up together.</color>",
  ui_story_40200001_101_option_content = "The Umbraton boy",
  ui_story_40200001_102_dialog_content = "That would be the harder of the two paths to take.",
  ui_story_40200001_103_dialog_content = "Not only would you never receive the blessings of your beloved's family, but you would also have to contend with animosity and possible revenge from both families all your life.",
  ui_story_40200001_104_dialog_content = "With no means of your own, all you would have to survive is your love for the Umbraton boy and the chains of your past.",
  ui_story_40200001_105_dialog_content = "It's a noble choice for sure, but I'm afraid only a few people would be able to make it.",
  ui_story_40200001_106_dialog_content = "Unfortunately, the Umbraton girl didn't make the same choice as you...",
  ui_story_40200001_107_dialog_content = "<color=#FFB400>In the end, the Umbraton girl and the noble girl end up together.</color>",
  ui_story_40200001_108_option_content = "The noble girl",
  ui_story_40200001_109_dialog_content = "What an unconventional choice.",
  ui_story_40200001_110_dialog_content = "Setting aside morality and ethics, and not allowing the fetters of the past or present to hold you back...",
  ui_story_40200001_111_dialog_content = "<color=#FFB400>This, in fact, is the true ending to the story.</color>",
  ui_story_40200001_112_dialog_content = "I never thought Nameless would be so keen on this subject.",
  ui_story_40200001_113_dialog_content = "Eh? W-Wait a second!",
  ui_story_40200001_114_dialog_content = "What the heck happens between the two of them, that they end up together in the end?!",
  ui_story_40200001_115_dialog_content = "You'll have to find the answer to that... By reading the book yourself.",
  ui_story_40200001_116_dialog_content = "Allow me to explain, my dear Nameless.",
  ui_story_40200001_117_dialog_content = "This Lady doesn't care about the love described in this book.",
  ui_story_40200001_118_dialog_content = "All she cares about are the exaggerated and contrived plots so characteristic of these kinds of stories.",
  ui_story_40200001_119_dialog_content = "Multiple love interests, entrapment, and maybe some sadomasochistic elements for that extra kick.",
  ui_story_40200001_120_dialog_content = "I strongly suggest you avoid this kind of unhealthy reading, or else your brain might turn to mush.",
  ui_story_40200001_121_dialog_content = "Oh, what do you know? Reading's only exciting when it's hot and flustered like this.",
  ui_story_40200001_122_dialog_content = "I think everyone should take a look at my suggestion, instead, A Musician's Life.",
  ui_story_40200001_123_dialog_content = "The main character of the story Mr. Litman, the great pianist who composed \"Litman's Polka.\"",
  ui_story_40200001_124_dialog_content = "An orphan without a name, he lived a life of solitude.",
  ui_story_40200001_125_dialog_content = "His right leg was also partially paralyzed.",
  ui_story_40200001_126_dialog_content = "In the pub of a tiny, unnamed town, he played the piano for all of his life.",
  ui_story_40200001_127_dialog_content = "It wasn't until after his death, that his beautiful compositions were discovered and spread across the world.",
  ui_story_40200001_128_dialog_content = "Though his life was so bleak and unfortunate, his musical works were both powerful and uplifting.",
  ui_story_40200001_129_dialog_content = "A trumpeter with whom he had collaborated left an engraving upon his tombstone, a single sentence:",
  ui_story_40200001_130_dialog_content = "In music, there is life.",
  ui_story_40200001_131_dialog_content = "Well, it sounds compelling, but... It doesn't sound like there are any elements of love in the story?",
  ui_story_40200001_132_dialog_content = "You mean you didn't realize that Mr. Litman <color=#FFB400>happily spent his entire life with his music</color>?",
  ui_story_40200001_133_dialog_content = "You couldn't ask for a more perfect ending!",
  ui_story_40200001_134_dialog_content = "While it IS true that you can see a kind of love in this book, I'm afraid it isn't particularly deep.",
  ui_story_40200001_135_dialog_content = "What I would recommend is this book, \"A Thousand Years of Silence.\"",
  ui_story_40200001_136_dialog_content = "It tells the story of a builder who can neither age nor die, and how he copes with his longevity on his own.",
  ui_story_40200001_137_dialog_content = "After the death of his last lover...",
  ui_story_40200001_138_dialog_content = "He devotes the next thousand years to building an immense, underground mausoleum for himself, one that spans hundreds of stories in-depth, and ultimately falls into a deep slumber at the very bottom.",
  ui_story_40200001_139_dialog_content = "Later generations uncovered the builder's tomb and were awestruck by its exquisite craftsmanship. The builder was then revered as a founder of architecture.",
  ui_story_40200001_140_dialog_content = "I think the protagonist truly understood the <color=#FFB400>essence of love</color>.",
  ui_story_40200001_141_dialog_content = "Spanning across both time and space, love is everywhere and, at the same time, nowhere.",
  ui_story_40200001_142_dialog_content = "Perhaps only something as firm as The Truth could be called love.",
  ui_story_40200001_143_dialog_content = "Now it's your turn, Snowball- I mean, Nameless. Ugh, Snowball suits you so much better, though...",
  ui_story_40200001_144_dialog_content = "M-My turn?",
  ui_story_40200001_145_dialog_content = "This is a reading club, after all, so now it's your turn to share a book with us. Or could it be... You didn't prepare one?",
  ui_story_40200001_146_dialog_content = "We aren't trying to embarrass you or anything, but... Did you not bring any books?",
  ui_story_40200001_147_dialog_content = "What about the books that the previous Nameless gave you? You could read those.",
  ui_story_40200001_148_dialog_content = "O-Oh, yeah.",
  ui_story_40200001_149_dialog_content = "Let me see... Wait a minute, these books...",
  ui_story_40200001_150_dialog_content = "(\"How to Cultivate Tentacles\"? \"My Favorite Skeleton\"?? \"Interrogations and Blood: A Love Story\"???)",
  ui_story_40200001_151_dialog_content = "(Warning: Not intended for underage readers...)",
  ui_story_40200001_152_dialog_content = "(...)",
  ui_story_40200001_153_dialog_content = "<size=45>(Sweet mercy, what kind of books did you give me, Eicy!?)</size>",
  ui_story_40200001_154_dialog_content = "Come on now. Share with the group.",
  ui_story_40200001_155_dialog_content = "I don't think I can!",
  ui_story_40200001_156_dialog_content = "L-Look! This book's title has even been scribbled out with a pen! I'm sure it's nothing worth sharing!",
  ui_story_40200001_157_dialog_content = "Well, when it comes to HER preferences, it can't be anything decent.",
  ui_story_40200001_158_dialog_content = "But sharing is a necessary part of our reading club, and Snowball is no exception. Now read for us, nice and loudly.",
  ui_story_40200001_159_dialog_content = "This is an inviolable rule of the Hidden Moon Reading Club.",
  ui_story_40200001_160_dialog_content = "I... I...",
  ui_story_40200001_161_dialog_content = "Here, let me...",
  ui_story_40200001_162_dialog_content = "Huh?",
  ui_story_40200001_163_dialog_content = "I can stand in for PlayerName... I'll share in his place.",
  ui_story_40200001_164_dialog_content = "Now, this is a surprise! I've never seen Maiden take such initiative!",
  ui_story_40200001_165_dialog_content = "The floor is yours, Maiden.",
  ui_story_40200001_166_dialog_content = "What I understand about love is... <color=#FFB400>Romance</color>...",
  ui_story_40200001_167_dialog_content = "Compared to everyone else's understanding, mine might seem insignificant...",
  ui_story_40200001_168_dialog_content = "That's alright, just say what you want to say and we'll listen.",
  ui_story_40200001_169_dialog_content = "I recommend this book, \"The Viridian Grove.\"",
  ui_story_40200001_170_dialog_content = "It's about a depressed artist, who meets a sad-looking girl while sketching deep in the forest.",
  ui_story_40200001_171_dialog_content = "Even though he only just met her, he falls in love at first sight...",
  ui_story_40200001_172_dialog_content = "And he begins sketching the girl with his pencil.",
  ui_story_40200001_173_dialog_content = "At first, the girl is really embarrassed and wants nothing to do with the artist...",
  ui_story_40200001_174_dialog_content = "But over time, she begins to see her beauty in the artist's sketches.",
  ui_story_40200001_175_dialog_content = "Afterwards, they begin experiencing all sorts of firsts together...",
  ui_story_40200001_176_dialog_content = "And in the process, they gradually grow and overcome their imperfect selves.",
  ui_story_40200001_177_dialog_content = "...",
  ui_story_40200001_178_dialog_content = "...",
  ui_story_40200001_179_dialog_content = "...",
  ui_story_40200001_180_dialog_content = "Y-You, don't like it? Should I pick a different book?",
  ui_story_40200001_181_dialog_content = "No, I think it's a very good story.",
  ui_story_40200001_182_dialog_content = "... Oh, really?",
  ui_story_40200001_183_dialog_content = "Beryl is still very young, isn't she? An honest-to-goodness maiden.",
  ui_story_40200001_184_dialog_content = "Young people's ideas of love are so pure and happy, aren't they?",
  ui_story_40200001_185_dialog_content = "But there's nothing wrong with that, you know? Think of all the songs ever written about sweet, innocent love.",
  ui_story_40200001_186_dialog_content = "Even though Mr. Litman never married in all his life...",
  ui_story_40200001_187_dialog_content = "He composed one of the most beautiful waltzes in history, and its name is \"The Joyful Bride.\"",
  ui_story_40200001_188_dialog_content = "Just thinking about it almost makes me want to fall in love, myself.",
  ui_story_40200001_189_dialog_content = "But you need a partner for romantic love, don't you? An object of affection?",
  ui_story_40200001_190_dialog_content = "We have Snowball, don't we? We could write lots of stories about this cutie...",
  ui_story_40200001_191_dialog_content = "Eh? Me?",
  ui_story_40200001_192_dialog_content = "Yep.",
  ui_story_40200001_193_dialog_content = "Writing stories about our bucking bronco, the Navigator? That sounds like fun!",
  ui_story_40200001_194_dialog_content = "Yes, even I can't help but agree.",
  ui_story_40200001_195_dialog_content = "My creative juices are already flowing!",
  ui_story_40200001_196_dialog_content = "(Even though they're all looking at me...)",
  ui_story_40200001_197_dialog_content = "(Something tells me they're not going to write anything like Beryl's romantic story...)",
  ui_story_40200001_198_dialog_content = "(But some crazy, bizarre stories that'll make me freak out...)",
  ui_story_40200001_199_dialog_content = "To be continued..."
}
return config
